const limit = new Date();
limit.setDate(limit.getDate() + 60);
const limitISO = limit.toISOString().split("T")[0];

const baseUrl = env.get("SUPABASE_URL");
const apiKey  = env.get("SUPABASE_SERVICE_ROLE_KEY") || env.get("SUPABASE_ANON_KEY");

if (!baseUrl || !apiKey) {
    node.error("Chybi SUPABASE_URL nebo SUPABASE_SERVICE_ROLE_KEY / SUPABASE_ANON_KEY");
    return null;
}

msg.url = `${baseUrl}/rest/v1/certificates_expiring_soon` +
          `?expires_at=lte.${limitISO}` +
          `&select=certificate_id,certificate_number,first_name,phone,expires_at`;

msg.headers = {
    "apikey": apiKey,
    "Authorization": `Bearer ${apiKey}`,
    "Content-Type": "application/json",
    "Prefer": "return=representation"
};

msg.requestTimeout = 15000;
return msg;

const cert = msg.payload;
const THRESHOLDS = [60, 30, 14, 7, 3, 1];

if (!cert || !cert.expires_at || !cert.phone) {
    return null;
}

const today = new Date();
today.setHours(0, 0, 0, 0);

const expires = new Date(cert.expires_at);
expires.setHours(0, 0, 0, 0);

const daysLeft = Math.round((expires - today) / 86400000);

if (!THRESHOLDS.includes(daysLeft)) {
    return null;
}

const expiryDate = expires.toLocaleDateString("cs-CZ");

let urgency = "";
if (daysLeft === 1) urgency = " (zitra!)";
else if (daysLeft <= 3) urgency = " (brzy!)";

msg.payload =
    `Dobry den ${cert.first_name || ""}, ` +
    `Vas certifikat ${cert.certificate_number} ` +
    `vyprsi za ${daysLeft} ${daysLeft === 1 ? "den" : "dni"} (${expiryDate})${urgency}. ` +
    `Prosim kontaktujte sveho poskytovatele ohledne obnoveni skoleni.`;

msg.phone = cert.phone;
msg.certificate_id = cert.certificate_id;
msg.days_left = daysLeft;

return msg;

const sid   = env.get("TWILIO_ACCOUNT_SID");
const token = env.get("TWILIO_AUTH_TOKEN");
const from  = env.get("TWILIO_FROM_NUMBER");

if (!sid || !token || !from) {
    node.error("Chybi TWILIO_ACCOUNT_SID / TWILIO_AUTH_TOKEN / TWILIO_FROM_NUMBER");
    return null;
}

msg.url = `https://api.twilio.com/2010-04-01/Accounts/${sid}/Messages.json`;

msg.headers = {
    "Authorization": "Basic " + Buffer.from(`${sid}:${token}`).toString("base64"),
    "Content-Type": "application/x-www-form-urlencoded"
};

msg.payload = new URLSearchParams({
    To: msg.phone,
    From: from,
    Body: msg.payload
}).toString();

msg.twilioBody = msg.payload;
msg.requestTimeout = 10000;

return msg;

const MAX = flow.get("twilioMaxRetry") || 5;
const code = msg.statusCode;

if (code >= 200 && code < 300) {
    return [null, null, msg];
}

const retryable = code === undefined || code === 429 || code >= 500;

msg.retry = (msg.retry || 0) + 1;

if (retryable && msg.retry <= MAX) {
    msg.payload = msg.twilioBody;
    msg.delay = 2000 * Math.pow(2, msg.retry - 1);
    return [msg, null, null];
}

return [null, {
    payload: {
        failed_at: new Date().toISOString(),
        certificate_id: msg.certificate_id,
        phone: msg.phone,
        days_left: msg.days_left,
        status: code ?? "network",
        error: msg.error?.message ?? msg.payload?.message ?? "unknown",
        attempts: msg.retry
    }
}, null];
